import { TimeRuler, Button } from "march/ui"

// bir yumurta zamanlayıcısı: cetveli sürükleyerek pişme süresini seç (dakikaya yapışır), etiketler dakika yazar
const MIN = 60_000

export function EggTimer() {
  let $at = 6 * MIN
  const egg = () => $at <= 4 * MIN ? "rafadan 🥚" : $at <= 7 * MIN ? "kayısı 🍳" : "katı 🥚"
  return <div sx={{ flex: "col", gap: 2 }}>
    <TimeRuler duration={12 * MIN} value={() => $at} onSeek={(ms: number) => $at = ms} major={2 * MIN} step={MIN}
      format={(ms: number) => `${ms / MIN} dk`} valueText={(ms: number) => `${Math.round(ms / MIN)} dakika`}
      snap={(ms: number) => Math.round(ms / MIN) * MIN} m:color="brand-orange" labels={{ ruler: "Pişme süresi", playhead: "Süre" }} />
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <span sx={{ text: "bold" }}>{() => `${$at / MIN} dakika: ${egg()}`}</span>
      <Button size="sm" on:click={() => $at = 6 * MIN}>Sıfırla</Button>
    </div>
  </div>
}

import { TimeRuler, Card } from "march/ui"

// TimeRuler'ın bütün özellikleri bir arada: duration, value, onSeek, onSeekStart, step, major, minor, ticks, format,
// valueText, snap, keyStep, head (yok / kendi), headClass, labels ve class
export function TimeRulerLab() {
  let $ms = 1500
  let $starts = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <p>Konum: <b>{() => `${$ms} ms`}</b> · sürükleme / tuş: <b>{() => $starts}</b></p>
    <TimeRuler class="lab-ruler" duration={() => 4000} value={() => $ms} onSeek={(ms: number) => $ms = Math.round(ms)} onSeekStart={() => $starts++}
      step={250} major={1000} keyStep={500} snap={(ms: number) => Math.round(ms / 250) * 250}
      valueText={(ms: number) => `${ms} milisaniye`} headClass="lab-head" labels={{ ruler: "Lab cetveli", playhead: "Lab başı" }} />
    <TimeRuler duration={4000} value={() => $ms} minor={false} format={(ms: number) => `${ms / 1000} sn`} m:color="brand-purple"
      head={<span aria-hidden="true">▼</span> as Node} />
    <TimeRuler duration={3000} ticks={(d: number) => [{ at: 0, major: true, label: "başla" }, { at: d / 2, label: "yarı" }, { at: d, major: true, label: "bitir" }]} />
    <Card m:theme="night">
      <TimeRuler duration={4000} value={() => $ms} head={false} />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { TimeRulerLab } from "./TimeRulerLab.tsx"

// TimeRulerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("onSeek'li cetvel bir grup, başı bir kaydırıcı; labels adları verir", () => {
  const s = renderTest(() => <TimeRulerLab />)
  const ruler = s.get(".lab-ruler")!
  expect(ruler.getAttribute("aria-label")).toBe("Lab cetveli")
  const head = ruler.querySelector(".lab-head")!
  expect(head.getAttribute("role")).toBe("slider")
  expect(head.getAttribute("aria-label")).toBe("Lab başı")
  expect(head.getAttribute("aria-valuetext")).toBe("1500 milisaniye")
})

test("→ tuşu keyStep kadar ilerletir ve onSeekStart sayar", async () => {
  const s = renderTest(() => <TimeRulerLab />)
  const head = s.get(".lab-head")!
  head.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowRight", bubbles: true }))
  await s.flush()
  expect(s.sees("Konum: 2000 ms")).toBe(true)
  expect(s.sees("sürükleme / tuş: 1")).toBe(true)
})

test("ticks kendi etiketlerini, format kendi biçimini yazar", () => {
  const s = renderTest(() => <TimeRulerLab />)
  expect(s.sees("yarı")).toBe(true)
  expect(s.sees("2 sn")).toBe(true)
})
